{
  "packet_id": "H6-T03-1",
  "claim_id": "C022",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C022.component",
    "value": "An attachment's presence alone does not establish approval before order placement.",
    "scope": "A general evidentiary distinction, also expressed as a proposed test for attachments lacking demonstrated prior approval; that example is not a finding about sampled orders.",
    "provenance": {
      "refs": [
        {"source_id": "P017", "role": "SUPPORT"},
        {"source_id": "P018", "role": "SUPPORT"},
        {"source_id": "P022", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P022 states the distinction directly; P017 and P018 establish its proposed observational form and exclude treating it as a finding."
    }
  },
  "signal_basis": {
    "component_id": "C022.signal_basis",
    "value": "Distinguish event, record-creation and attachment dates, and test whether linked approval records demonstrate approval before placement. The proposed discrepancies include attachments without demonstrated prior approval.",
    "scope": "Documentary checks on sampled orders; the discrepancy examples are proposed observations, not established findings.",
    "provenance": {
      "refs": [
        {"source_id": "P009", "role": "SUPPORT"},
        {"source_id": "P015", "role": "SUPPORT"},
        {"source_id": "P017", "role": "SUPPORT"},
        {"source_id": "P018", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the distinct dates, order linkage and temporal test, together with the attachment discrepancy and its proposed status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C022.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The supported evidentiary distinction requires no unresolved empirical relation."
    }
  },
  "rationale": "An attachment's existence does not by itself establish the timing of the approval it purports to document. The operation separately checks approval timing and distinguishes it from record creation and attachment timing, licensing this limited claim without implying that approval was absent.",
  "uncertainty": "No material uncertainty about this warrant; whether any sampled attachment demonstrates prior approval remains an order-specific evidence question.",
  "anomalies": []
}
